create table if not exists public.payroll_staff_statements(
 id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade,
 payroll_run_id uuid not null references public.payroll_runs(id) on delete cascade,
 run_employee_id uuid not null references public.payroll_run_employees(id) on delete cascade,
 employee_id uuid not null references public.hr_employees(id), amount_due numeric(14,2) not null default 0,
 amount_paid numeric(14,2) not null default 0,balance numeric(14,2) not null default 0,
 status text not null default 'unpaid' check(status in('unpaid','part_paid','paid')),
 last_payment_date date,last_payment_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(run_employee_id));
create table if not exists public.payroll_staff_payment_transactions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,
 statement_id uuid not null references public.payroll_staff_statements(id) on delete cascade,
 amount numeric(14,2) not null check(amount>0),payment_date date not null default current_date,reference text not null,
 recorded_by uuid default auth.uid(),created_at timestamptz not null default now());
alter table public.payroll_staff_statements enable row level security;alter table public.payroll_staff_payment_transactions enable row level security;
drop policy if exists staff_statements_tenant on public.payroll_staff_statements;create policy staff_statements_tenant on public.payroll_staff_statements for all to authenticated using(public.is_tenant_member(tenant_id)) with check(public.is_tenant_member(tenant_id));
drop policy if exists staff_payment_tx_tenant on public.payroll_staff_payment_transactions;create policy staff_payment_tx_tenant on public.payroll_staff_payment_transactions for all to authenticated using(public.is_tenant_member(tenant_id)) with check(public.is_tenant_member(tenant_id));
create or replace function public.payroll_generate_staff_statements(p_tenant uuid,p_run uuid) returns integer language plpgsql security definer set search_path=public as $$declare n integer;begin if not public.has_tenant_role(p_tenant,array['owner','administrator','accountant','finance_manager','payroll_manager','payroll_officer']) then raise exception 'Payroll access denied';end if;if not exists(select 1 from payroll_runs where id=p_run and tenant_id=p_tenant and status='posted') then raise exception 'Payroll must be posted before staff statements are generated';end if;insert into payroll_staff_statements(tenant_id,payroll_run_id,run_employee_id,employee_id,amount_due,amount_paid,balance,status) select p_tenant,p_run,r.id,r.employee_id,r.net_pay,0,r.net_pay,'unpaid' from payroll_run_employees r where r.run_id=p_run on conflict(run_employee_id) do update set amount_due=excluded.amount_due,balance=greatest(excluded.amount_due-payroll_staff_statements.amount_paid,0),status=case when payroll_staff_statements.amount_paid>=excluded.amount_due then 'paid' when payroll_staff_statements.amount_paid>0 then 'part_paid' else 'unpaid' end,updated_at=now();get diagnostics n=row_count;return n;end$$;
create or replace function public.payroll_record_staff_payment(p_tenant uuid,p_statement uuid,p_amount numeric,p_reference text) returns jsonb language plpgsql security definer set search_path=public as $$declare s payroll_staff_statements%rowtype;np numeric;nb numeric;begin if not public.has_tenant_role(p_tenant,array['owner','administrator','accountant','finance_manager','payroll_manager','payroll_officer']) then raise exception 'Payroll access denied';end if;select * into s from payroll_staff_statements where id=p_statement and tenant_id=p_tenant for update;if s.id is null then raise exception 'Staff payroll statement not found';end if;if p_amount<=0 or p_amount>s.balance then raise exception 'Payment must be greater than zero and not exceed outstanding balance';end if;insert into payroll_staff_payment_transactions(tenant_id,statement_id,amount,reference) values(p_tenant,p_statement,p_amount,p_reference);np:=s.amount_paid+p_amount;nb:=greatest(s.amount_due-np,0);update payroll_staff_statements set amount_paid=np,balance=nb,status=case when nb=0 then 'paid' else 'part_paid' end,last_payment_date=current_date,last_payment_reference=p_reference,updated_at=now() where id=s.id;return jsonb_build_object('ok',true,'paid',np,'balance',nb);end$$;
grant execute on function public.payroll_generate_staff_statements(uuid,uuid) to authenticated;grant execute on function public.payroll_record_staff_payment(uuid,uuid,numeric,text) to authenticated;
